import catalog from "./bundled-plugins.generated.json" with { type: "json" };

/**
 * AI-DLC plugins the extension ships, as the 「プラグイン」 page shows them.
 *
 * The catalog is generated by `scripts/build-bundled-plugins.ts` from each plugin's
 * `.andon/listing.json` and from composing the plugin into a copy of this repository's
 * `.claude/`, and is committed; `bun run check:plugins-catalog` fails when it is stale. Both the
 * dashboard and the extension read it at build time, so the browser needs no API for it.
 */

/** How a stage of the plugin's scope relates to the standard workflow. */
export type BundledPluginStageOrigin = "plugin" | "core-extended" | "core";

export interface BundledPluginStage {
  slug: string;
  /** The stage's display name from the compiled stage graph. */
  name: string;
  phase: string;
  origin: BundledPluginStageOrigin;
  /** Whether the stage runs once per Unit of work. */
  perUnit: boolean;
}

export interface BundledPluginRequirement {
  id: string;
  /** `required` blocks installing; `recommended` and `info` only explain. */
  level: "required" | "recommended" | "info";
  label: string;
  detail: string;
}

export interface BundledPlugin {
  /** The plugin key, as `aidlc engine plugin select` names it. */
  name: string;
  version: string;
  /** The engine's hash of the composed sources, which the install record pins. */
  sourceHash: string;
  title: string;
  tagline: string;
  summary: string;
  /** `preview` until the plugin has been tried on real work. */
  status: "preview" | "stable";
  /** The harness the plugin is composed into. */
  harness: string;
  scope: string;
  startCommand: string;
  fitFor: string[];
  notFitFor: string[];
  requirements: BundledPluginRequirement[];
  /** The stages the scope runs past initialization, in workflow order. */
  stages: BundledPluginStage[];
  /**
   * Paths in the harness tree, sorted, that composing and selecting the plugin adds or changes.
   * Selecting also writes one audit entry to the workflow record (`aidlc/`), which is not listed.
   */
  files: { added: string[]; changed: string[] };
  /** A diagram drawn as an example of what the plugin produces. */
  sample: { alt: string; svg: string } | null;
}

export interface BundledPluginCatalog {
  schemaVersion: 1;
  plugins: BundledPlugin[];
}

export const BUNDLED_PLUGINS: BundledPluginCatalog = catalog as BundledPluginCatalog;
